        raise ValueError("Invalid ISBN format. Expected format: 'x-xxx-xxxxx-x'")

    # Extract the six digits excluding the check digit
    base_check_digits = isbn[:-1]

    # Calculate the checksum based on the ISBN standard
    checksum = 0
    for i, digit in enumerate(reversed(base_check_digits)):
        digit = int(digit)
        if i % 2 == 0:
            checksum += digit
        else:
