    # Calculate the checksum digit based on the formula
    checksum_digit = checksum % 11
    if checksum_digit == 10:
        checksum_digit = 'X'
    elif checksum_digit == 11:
        checksum_digit = '0'

    # Append the check digit to the original ISBN string
    corrected_isbn = isbn[:-1] + checksum_digit

    # Validate the corrected ISBN number
    if verify_isbn(corrected_isbn) == 'Right':
        return corrected_isbn
    else:
