    if not coeffs:
        return ''

    terms = []
    sign = 1
    for i, coeff in enumerate(coeffs[::-1]):
        if coeff == 0:
            continue
        term = str(abs(coeff)) if abs(coeff) != 1 else ''
        degree = n - i if i < n else 0
        if degree > 1:
            term += f'^{degree}'
        elif degree == 1:
            term += str('x' if i == 0 else '')
        terms.append(f"{sign if sign != 1 else ''}{term}")
        sign *= -1

    return ''.join(terms)

