def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x:
        return 0

    def count_partitions_recur(n, k, x, cache):
        if (n, k, x) in cache:
            return cache[(n, k, x)]
        if n < k:
            cache[(n, k, x)] = 0
        elif n == k:
            cache[(n, k, x)] = 1
        else:
            count = 0
            for i in range(x, n // k + 1):
                count += count_partitions_recur(n - i, k - 1, x, cache)
            cache[(n, k, x)] = count
        return cache[(n, k, x)]

    cache = {}
    return count_partitions_recur(n, k, x, cache)

